  lobbying:{title:'Lobbying by top donor organizations',body:x=>`<p class="live-footnote">Up to 25 filings a year for each organization, back to 2016.</p>${yearCounts(x.byYear,'Filings read by year')}`+yearly(x.rows,r=>li(r.url,`${r.org} · ${r.registrant||'self-filed'}`,`${esc(r.period||'')} ${esc(r.year||'')}${r.amount?' · '+cash(r.amount):''}${r.issues?.length?' · '+esc(r.issues.join(', ')):''}${r.bills?.length?' · Bills: '+esc(r.bills.map(billName).join(', ')):''}`),'No lobbying filings found for their top donor organizations.',20)},
