  sam:{title:'Company federal IDs (SAM.gov)',body:x=>ul(x.rows,r=>li(null,r.org,r.uei?`UEI ${esc(r.uei)} · ${esc(r.name)}`:`<span class="live-warning">${esc(r.review)}</span>`),'No organizations checked yet.')},
  contracts:{title:'Federal contracts to top donor organizations',body:x=>`<p class="live-meta">${cash(x.total)} in the largest awards found, from fiscal year 2016 on. <b>Context only:</b> not proof of influence.</p>${ul(x.rows.slice(0,20),r=>li(r.url,`${r.org} · ${cash(r.amount)}`,`${esc(r.agency||'')} · ${date(r.date)}${r.description?' · '+esc(r.description):''}`),'No contracts found.')}`},
  // Sources that cover the same thing, joined into one card each (src/merge.mjs). sources: the jobs behind the card, so
